minhook = {
  source = path.join(dependencies.basePath, "minhook"),
}

function minhook.import()
  links({ "minhook" })
  minhook.includes()
end

function minhook.includes()
  includedirs({
    path.join(minhook.source, "include"),
  })
end

-- Xerces (DESIGN.md 12.4): MinHook's hook.c is compiled from a copy made here,
-- whose thread walk for Freeze() covers only this process
-- (src/xerces_deps/minhook/minhook_threads.inc). The submodule stays as it is.
-- Each change must match exactly once, or premake stops: a MinHook update
-- that moves the code needs the patch redone, not silently skipped.
function minhook.patched_hook_c()
  local source = path.join(minhook.source, "src/hook.c")
  local text = io.readfile(source)
  assert(text, "minhook patch: cannot read " .. source)
  text = text:gsub("\r\n", "\n")
  -- hook.c starts with a UTF-8 byte-order mark; the header goes before it.
  if text:sub(1, 3) == "\239\187\191" then
    text = text:sub(4)
  end

  local function replace_once(old, new)
    local first, last = text:find(old, 1, true)
    assert(first, "minhook patch: not found in hook.c: " .. old)
    assert(not text:find(old, last + 1, true), "minhook patch: found twice in hook.c: " .. old)
    text = text:sub(1, first - 1) .. new .. text:sub(last + 1)
  end

  replace_once('#include "../include/MinHook.h"', '#include "MinHook.h"')
  replace_once(
    "static BOOL EnumerateThreads(PFROZEN_THREADS pThreads)\n{",
    "static BOOL EnumerateThreadsSnapshot(PFROZEN_THREADS pThreads)\n{"
  )
  replace_once(
    "//-------------------------------------------------------------------------\nstatic MH_STATUS Freeze(",
    '#include "minhook_threads.inc"\n\n'
      .. "//-------------------------------------------------------------------------\nstatic MH_STATUS Freeze("
  )

  local out = path.join(_MAIN_SCRIPT_DIR, "build/generated/minhook/hook.c")
  os.mkdir(path.getdirectory(out))
  local header = "/* Generated by deps/premake/minhook.lua from deps/minhook/src/hook.c\n"
    .. "   (MinHook, BSD 2-clause) with Xerces' thread walk. Do not edit. */\n"
  local wrote = io.writefile(out, header .. text)
  assert(wrote ~= false, "minhook patch: cannot write " .. out)
  return out
end

function minhook.project()
  project("minhook")
  language("C")

  minhook.includes()
  includedirs({
    path.join(minhook.source, "src"),
    path.join(_MAIN_SCRIPT_DIR, "src/xerces_deps/minhook"),
  })

  files({
    path.join(minhook.source, "src/**.h"),
    path.join(minhook.source, "src/**.c"),
  })
  removefiles({ path.join(minhook.source, "src/hook.c") })
  files({ minhook.patched_hook_c() })

  warnings("Off")
  kind("StaticLib")
end

table.insert(dependencies, minhook)
